import styled from '@emotion/styled';

export const StyledPillarContainer = styled.div({
  display: 'flex',
  flexDirection: 'row',
  justifyContent: 'space-between',
  width: '100%',
  gap: '24px',
});

export const StyledPillarDetails = styled.div({
  display: 'flex',
  flexDirection: 'column',
  justifyContent: 'space-between',
  maxWidth: '600px',
  gap: '24px',
});

export const StyledHighlightedTraining = styled.div({
  display: 'flex',
  flexDirection: 'row',
  gap: '16px',
  marginTop: '-56px',
});

export const StyledPillarDetailsText = styled.div<{
  titleSize: 'xl' | 'lg';
  hideIf?: boolean;
}>(
  {
    display: 'flex',
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'start',
    gap: '8px',
    margin: 0,
    fontFamily: 'Work sans',
    fontWeight: 400,
    fontSize: '28px',
    lineHeight: '140%',
    letterSpacing: '0%',
    color: '#67665F',
  },
  (props) => ({
    fontSize: props.titleSize === 'xl' ? '28px' : '18px',
    display: props.hideIf && 'none',
  }),
);

export const StyledTotalTrainings = styled.p({
  fontWeight: 600,
  margin: 0,
});

export const StyledTrainingMaterialsTitle = styled.h2({
  fontFamily: 'Barlow',
  fontWeight: 600,
  fontSize: '24px',
  lineHeight: '140%',
  letterSpacing: '0%',
  color: '#141414',
  margin: '40px 0 16px 0',
});

export const StyledMaterialList = styled.div({
  display: 'grid',
  gridTemplateColumns: 'repeat(5, 1fr)',
  gap: '24px',
});
